namespace sv_ad34fe785f674d4aa1d878b3cdd42d65.Auth;

public sealed class UserInfo
{
    public required string Email { get; init; }
    public required string[] Roles { get; init; }
}

using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Server;
using Microsoft.AspNetCore.Components.Web;

namespace sv_ad34fe785f674d4aa1d878b3cdd42d65.Auth;

/// <summary>
/// Server-side AuthenticationStateProvider that simulates a logged-in user
/// and persists the auth state so the WebAssembly runtime can pick it up.
/// </summary>
public sealed class ServerAuthenticationStateProvider : ServerAuthenticationStateProvider<UserInfo>
{
    private static readonly UserInfo HardcodedUser = new()
    {
        Email = "bob@example.com",
        Roles = ["User", "Editor"]
    };

    public ServerAuthenticationStateProvider(PersistentComponentState persistentState)
        : base(persistentState)
    {
    }

    protected override UserInfo? MapToUserInfo(ClaimsPrincipal principal)
    {
        // We always return our hardcoded user regardless of the principal
        return HardcodedUser;
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
    {
        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, HardcodedUser.Email),
            new(ClaimTypes.Email, HardcodedUser.Email),
        };

        foreach (var role in HardcodedUser.Roles)
        {
            claims.Add(new Claim(ClaimTypes.Role, role));
        }

        var identity = new ClaimsIdentity(claims, authenticationType: "Hardcoded");
        var user = new ClaimsPrincipal(identity);

        return Task.FromResult(new AuthenticationState(user));
    }
}

using System.Diagnostics;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;

namespace sv_ad34fe785f674d4aa1d878b3cdd42d65.Auth;

/// <summary>
/// Base class that persists user info into PersistentComponentState so the
/// WebAssembly client can reconstruct the authentication state after handoff.
/// </summary>
public abstract class ServerAuthenticationStateProvider<TUserInfo> : AuthenticationStateProvider, IHostEnvironmentAuthenticationStateProvider, IDisposable
    where TUserInfo : class
{
    private readonly PersistentComponentState _persistentState;
    private readonly PersistingComponentStateSubscription _subscription;
    private Task<AuthenticationState>? _authStateTask;

    protected ServerAuthenticationStateProvider(PersistentComponentState persistentState)
    {
        _persistentState = persistentState;
        AuthenticationStateChanged += OnAuthenticationStateChanged;
        _subscription = _persistentState.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
    }

    public void SetAuthenticationState(Task<AuthenticationState> authenticationStateTask)
    {
        _authStateTask = authenticationStateTask;
        NotifyAuthenticationStateChanged(_authStateTask);
    }

    private void OnAuthenticationStateChanged(Task<AuthenticationState> task)
    {
        _authStateTask = task;
    }

    private async Task OnPersistingAsync()
    {
        if (_authStateTask is null)
        {
            // Fall back to getting it directly
            _authStateTask = GetAuthenticationStateAsync();
        }

        var authState = await _authStateTask;
        var principal = authState.User;

        if (principal.Identity?.IsAuthenticated == true)
        {
            var userInfo = MapToUserInfo(principal);
            if (userInfo is not null)
            {
                _persistentState.PersistAsJson("UserInfo", userInfo);
            }
        }
    }

    protected abstract TUserInfo? MapToUserInfo(System.Security.Claims.ClaimsPrincipal principal);

    public void Dispose()
    {
        _subscription.Dispose();
        AuthenticationStateChanged -= OnAuthenticationStateChanged;
    }
}

